    "synopsis": "O inverno aproxima-se de um mundo mergulhado no caos. No norte dos Sete Reinos está iminente uma batalha decisiva pelo que resta do antigo domínio dos Stark. Ainda mais a norte, Jon Snow luta por encontrar um equilíbrio entre as tradições da Patrulha da Noite e o que o seu instinto lhe diz ser o caminho correto a seguir. A sul, velhas alianças esperam o tempo certo para serem reveladas, enquanto os homens de ferro assolam os mares e as costas dos domínios Tyrell. Do outro lado do mar estreito, tudo converge para a Baía dos Escravos, onde Daenerys Targaryen tarda em ganhar a paz na inquieta cidade de Meereen. E os dragões? Qual será o seu papel no meio de tudo isto? Muitos estão certos de que a tão temida reconquista de Westeros está prestes a começar...",
