    "cover": "capas/book-302.jpeg",
    "synopsis": "Kull era um jovem bárbaro , nascido na Atlântida antes desta ter sido enconberta pelas àguas do mar. Abandonado pelos pais na floresta e criado por tigres , o menino viveu entre animais até que foi encontrado pela tribo do mar. Convivendo com os selvagens, ele atingiu a idade de se tornar um guerreiro. O velho feiticeiro da tribo declarou que o espírito do tigre seria seu simbolo e seu protetor. Dias depois, quando Kull e alguns companheiros chegavam de viagem à aldeia, o jovem atlante avistou uma multidão se prepando para queimar uma jovem. Revoltado ao saber que a nativa seria sacrificada por haver fugido com um pirata, e vendo que seria impossível salvá-la, ele a matou antes que o fogo tomasse seu corpo e a envolvesse num sofrimento insuportável. Considerado um traidor, todos se voltaram contra o rapaz, que mergulhou no mar e fugiu, sendo encontrado por piratas lemurianos . Escravizado pelos saqueadores, ele os serviu como remador, até que a caravela onde se encontrava ancorou próxima ao Reino de Valúsia, um dos países que compunham os chamados Sete Impérios. Fugindo da embarcação, ele foi capturado pelo valusianos e forçado a lutar na arena. Não demorou muito e, graças a sua força e coragem, Kull acabou se tornando um soldado, depois oficial até atingir o posto de comandante da Legião Negra, a tropa de elite do Rei Borna. Instigado por alguns nobres a assassinar o soberano para que o barão Kaanub assumisse o poder, Kull matou o monarca e decidiu ele mesmo usar a coroa real. Hoje Kull é um rei odiado por grande parte dos seu súditos, que o consideram um selvagem, indigno de governar um povo tão civilizado.",
