    "synopsis": "Esta antologia é fruto de uma votação feita entre escritores e críticos literários que escolheram seus contos prediletos do bruxo do Cosme Velho, resultando numa amostra significativa da prosa machadiana. Os trinta textos estão ordenados cronologicamente e receberam três acréscimos, apenas a título de curiosidade: o primeiro e o último contos escritos pelo autor — marcando uma produção que vai de 1858 a 1907 — e “O caso da vara”, que, embora muito conhecido e reproduzido em outras coletâneas, curiosamente não recebeu nenhum voto dos especialistas consultados. Com este livro, o leitor pode¬rá deleitar-se com essas histórias que foram elevadas à indiscutível categoria de obras-primas da literatura brasileira.",
