    "synopsis": "O modelo de negócios da Amazon é muito simples e torna fácil e conveniente a compra on-line, por isso os consumidores não pensam duas vezes em usar o site para suas compras. Isso se resume a praticamente um botão em cada página, o de comprar agora mesmo com um só clique. Qual a razão de a Amazon ser tão bem-sucedida? Isso muito tem a ver com Jeff Bezos, presidente e fundador da Amazon. A princípio mais um nerd do que um homem de negócios, Jeff teve a visão de investir no inexplorado mercado on-line para vender livros e continuou a descobrir novas oportunidades de mercado, de alimentos a peças de automóveis. Ele é uma verdadeira máquina de calcular, tem muita energia, é apaixonado pelo que faz e decidiu transformar radicalmente o varejo. Com inúmeras entrevistas com funcionários da Amazon, concorrentes e observadores, Richard Brandt decifrou como Bezos pensa, o que dirige suas ações e como ele toma decisões. Qualquer pessoa que esteja nesse negócio pode aprender muito com o exemplo de evolução contínua da Amazon.",
