    "synopsis": "O que o mito do rock Keith Richards revela em livro Vida surpreende até quem conviveu com ele, verdades até hoje não ditas. Imagina para os fãs do Rolling Stones? Em Vida , Keith Richards conta, de maneira crua e feroz, sua história, vivida de forma intensa no meio do fogo cruzado – desde a primeira infância, quando cresceu num bairro pobre ouvindo obsessivamente os discos de Chuck Berry e Muddy Waters, até o modo como levou a guitarra ao limite absoluto e uniu forças a Mick Jagger para formar os Rolling Stones. Com honestidade rasgada, Keith revela altos e baixos do rock’n’roll, a subida meteórica para a fama, as notórias prisões, as mulheres que teve, o vício em álcool e heroína. A lenda viva reconta como criou os solos envenenados que definiram Gimme Shelter e Honky Tonk Woman , seu romance com a infame Anita Pallenberg (mãe de três de seus filhos) e a morte trágica de Brian Jones. Da paixão por Patti Hansen a seu relacionamento com Mick Jagger, o leitor segue Keith em uma viagem inacreditável, porque é a jornada de um artista que vive sem temores e sem limites.",
